"use client";

import * as React from "react";
import * as DropdownMenuPrimitive from "@radix-ui/react-dropdown-menu";
import { Check, Search, X } from "lucide-react";

import { cn } from "@/lib/utils";

const DEFAULT_CONTENT_WIDTH = 280;
const SEARCHABLE_DROPDOWN_ITEM_NAME = "SearchableDropdownItem";
const SEARCHABLE_DROPDOWN_GROUP_NAME = "SearchableDropdownGroup";

type SearchableDropdownContextValue = {
  searchValue: string;
  hasResults: boolean;
};

const SearchableDropdownContext =
  React.createContext<SearchableDropdownContextValue | null>(null);

const SearchableDropdown = DropdownMenuPrimitive.Root;

const SearchableDropdownTrigger = DropdownMenuPrimitive.Trigger;

const SearchableDropdownPortal = DropdownMenuPrimitive.Portal;

function extractTextContent(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") {
    return String(node);
  }

  if (Array.isArray(node)) {
    return node.map((child) => extractTextContent(child)).join(" ");
  }

  if (React.isValidElement(node)) {
    return extractTextContent(
      (node.props as { children?: React.ReactNode }).children,
    );
  }

  return "";
}

function getComponentDisplayName(type: React.ElementType): string | undefined {
  if (typeof type === "string") {
    return type;
  }

  return (
    (type as { displayName?: string }).displayName ||
    (type as { name?: string }).name
  );
}

function matchesSearch(searchableText: string, searchValue: string): boolean {
  if (!searchValue.trim()) {
    return true;
  }

  return searchableText.toLowerCase().includes(searchValue.trim().toLowerCase());
}

function hasMatchingItems(
  children: React.ReactNode,
  searchValue: string,
): boolean {
  let hasMatch = false;

  React.Children.forEach(children, (child) => {
    if (hasMatch || !React.isValidElement(child)) {
      return;
    }

    const displayName = getComponentDisplayName(child.type as React.ElementType);
    const childProps = child.props as {
      children?: React.ReactNode;
      searchableText?: string;
    };

    if (displayName === SEARCHABLE_DROPDOWN_ITEM_NAME) {
      const searchableText =
        childProps.searchableText ?? extractTextContent(childProps.children);

      if (matchesSearch(searchableText, searchValue)) {
        hasMatch = true;
      }

      return;
    }

    if (displayName === SEARCHABLE_DROPDOWN_GROUP_NAME) {
      if (hasMatchingItems(childProps.children, searchValue)) {
        hasMatch = true;
      }

      return;
    }

    if (hasMatchingItems(childProps.children, searchValue)) {
      hasMatch = true;
    }
  });

  return hasMatch;
}

const SearchableDropdownContent = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Content> & {
    searchPlaceholder?: string;
    searchValue?: string;
    onSearchChange?: (value: string) => void;
    contentWidth?: React.CSSProperties["width"];
  }
>(
  (
    {
      className,
      sideOffset = 8,
      searchPlaceholder = "Search...",
      searchValue,
      onSearchChange,
      contentWidth = DEFAULT_CONTENT_WIDTH,
      children,
      style,
      ...props
    },
    ref,
  ) => {
    const inputRef = React.useRef<HTMLInputElement>(null);

    const [internalSearchValue, setInternalSearchValue] = React.useState("");

    const currentSearchValue = searchValue ?? internalSearchValue;
    const setSearch = onSearchChange ?? setInternalSearchValue;
    const hasResults = hasMatchingItems(children, currentSearchValue);

    React.useEffect(() => {
      const frame = window.requestAnimationFrame(() => {
        inputRef.current?.focus();
      });

      return () => {
        window.cancelAnimationFrame(frame);
      };
    }, []);

    return (
      <DropdownMenuPrimitive.Portal>
        <DropdownMenuPrimitive.Content
          ref={ref}
          sideOffset={sideOffset}
          className={cn(
            "z-50 overflow-hidden rounded-lg border border-[#e5e5e5] bg-white shadow-lg",
            "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 origin-[--radix-dropdown-menu-content-transform-origin]",
            className,
          )}
          style={{ width: contentWidth, ...style }}
          {...props}
        >
          <div className="border-b border-[#e5e5e5] px-4 py-3">
            <div className="flex items-center gap-3 rounded-lg border border-[#e6e6e6] bg-white px-3 py-2.5 transition-colors focus-within:border-[#1D1C20]">
              <Search className="size-5 flex-shrink-0 text-[#999999]" />
              <input
                ref={inputRef}
                type="text"
                placeholder={searchPlaceholder}
                value={currentSearchValue}
                onChange={(event) => setSearch(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key !== "Escape" && event.key !== "Tab") {
                    event.stopPropagation();
                  }
                }}
                className="flex-1 bg-transparent text-[14px] text-[#111111] outline-none placeholder:text-[#999999]"
                autoComplete="off"
                aria-label={searchPlaceholder}
              />
              {currentSearchValue ? (
                <button
                  type="button"
                  onClick={() => {
                    setSearch("");
                    inputRef.current?.focus();
                  }}
                  className="flex-shrink-0 text-[#999999] transition-colors hover:text-[#111111]"
                  aria-label="Clear search"
                >
                  <X className="size-4" />
                </button>
              ) : null}
            </div>
          </div>

          <SearchableDropdownContext.Provider
            value={{
              searchValue: currentSearchValue,
              hasResults,
            }}
          >
            <div className="max-h-[400px] overflow-y-auto">{children}</div>
          </SearchableDropdownContext.Provider>
        </DropdownMenuPrimitive.Content>
      </DropdownMenuPrimitive.Portal>
    );
  },
);
SearchableDropdownContent.displayName = "SearchableDropdownContent";

const SearchableDropdownGroup = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Group>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Group>
>(({ children, ...props }, ref) => {
  const context = React.useContext(SearchableDropdownContext);

  if (context && !hasMatchingItems(children, context.searchValue)) {
    return null;
  }

  return (
    <DropdownMenuPrimitive.Group ref={ref} {...props}>
      {children}
    </DropdownMenuPrimitive.Group>
  );
});
SearchableDropdownGroup.displayName = SEARCHABLE_DROPDOWN_GROUP_NAME;

const SearchableDropdownItem = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Item> & {
    searchValue?: string;
    searchableText?: string;
    isSelected?: boolean;
  }
>(
  (
    {
      className,
      searchValue,
      searchableText,
      isSelected = false,
      children,
      ...props
    },
    ref,
  ) => {
    const context = React.useContext(SearchableDropdownContext);

    const text = searchableText ?? extractTextContent(children);
    const currentSearchValue = searchValue ?? context?.searchValue ?? "";
    const isVisible = matchesSearch(text, currentSearchValue);

    if (!isVisible) {
      return null;
    }

    return (
      <DropdownMenuPrimitive.Item
        ref={ref}
        className={cn(
          "relative flex cursor-pointer select-none items-center justify-between px-4 py-3 text-[15px] text-[#111111] outline-none transition-colors hover:bg-[#f5f5f5] focus:bg-[#f5f5f5] data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
          className,
        )}
        {...props}
      >
        <span>{children}</span>
        {isSelected ? <Check className="size-5 text-[#26453f]" /> : null}
      </DropdownMenuPrimitive.Item>
    );
  },
);
SearchableDropdownItem.displayName = SEARCHABLE_DROPDOWN_ITEM_NAME;

const SearchableDropdownEmpty = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => {
  const context = React.useContext(SearchableDropdownContext);

  if (context?.hasResults) {
    return null;
  }

  return (
    <div
      ref={ref}
      className={cn("px-4 py-6 text-center text-sm text-[#666666]", className)}
      {...props}
    />
  );
});
SearchableDropdownEmpty.displayName = "SearchableDropdownEmpty";

const SearchableDropdownLabel = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    className={cn("px-4 py-2 text-sm font-semibold text-[#666666]", className)}
    {...props}
  />
));
SearchableDropdownLabel.displayName = "SearchableDropdownLabel";

const SearchableDropdownSeparator = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <DropdownMenuPrimitive.Separator
    ref={ref}
    className={cn("mx-0 my-0 h-px bg-[#e5e5e5]", className)}
    {...props}
  />
));
SearchableDropdownSeparator.displayName = "SearchableDropdownSeparator";

export {
  SearchableDropdown,
  SearchableDropdownTrigger,
  SearchableDropdownContent,
  SearchableDropdownItem,
  SearchableDropdownEmpty,
  SearchableDropdownLabel,
  SearchableDropdownSeparator,
  SearchableDropdownGroup,
  SearchableDropdownPortal,
};
